import{_ as i,l as n,o as e,c as l,v as t,p as s,x as o,d as c,i as p,S as E}from"./chunks/framework.InCnrqk-.js";const x=JSON.parse('{"title":"比较静态","description":"","frontmatter":{"title":"比较静态","date":"2026-09-10T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/comparative-statics.md","filePath":"econ/comparative-statics.md","lastUpdated":1789023840000}'),h={name:"econ/comparative-statics.md"};function d(m,a,A,B,_,u){const r=n("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="比较静态" tabindex="-1">比较静态 <a class="header-anchor" href="#比较静态" aria-label="Permalink to &quot;比较静态&quot;">​</a></h1><div class="epigraph"><p>参数动，最优怎么动：符号来自隐函数的矩阵，不必解出闭式需求。</p><footer>—— 据 Mas-Colell, Whinston and Green 第 2–3 章与数学附录；Silberberg, The Structure of Economics, 选章整理</footer></div><p>上一课<a href="/econ/implicit-function">隐函数定理</a>给出 \\(Dx=-(D_x F)^{-1}D_\\theta F\\)。缺口是把矩阵翻译成经济学语句：价格升、收入升、税率升，选择升还是降。本课只补「读符号」这一层，并标明何时必须上显示偏好或单调性方法，而不是硬微分。<a href="/econ/envelope-theorem">包络定理</a>管值，\\(x\\) 的移动是另一本账，不要互相代替。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>标准消费者：FONC \\(\\nabla u=\\lambda p\\)，加预算。对 \\((p,w)\\) 微分得到斯勒茨基方程的微分形式。本课不把<a href="/econ/slutsky-equation">斯勒茨基方程</a>整章重写，只指出比较静态的分工：自身价格效应分解成替代（负半定）与收入；交叉价格没有符号，除非再加总替代、位似或拟线性。厂商要素需求对自身要素价格通常下降（凹生产或凸成本），对产出价格上升——符号来自利润最大化的二阶结构，不是来自「直觉上应该」。</p><p>宏观的稳态比较静态同一套：Ramsey 里 \\(\\beta\\) 变、折旧变，资本存量沿欧拉方程的 Jacobian 动。后课<a href="/econ/ramsey-cass-koopmans">Ramsey–Cass–Koopmans</a>会用；这里只要求会读：先写均衡或最优的方程 \\(F(x,\\theta)=0\\)，再对非奇异 Jacobian 求线性响应。</p><h3 id="比较静态不是比较动态" tabindex="-1">比较静态不是比较动态 <a class="header-anchor" href="#比较静态不是比较动态" aria-label="Permalink to &quot;比较静态不是比较动态&quot;">​</a></h3><p>比较静态比较两个稳态或两个最优，不描写怎么走过去。调整路径、鞍点稳定、转向是动态系统的事，后课压缩映射与贝尔曼才管。把 \\(dx/d\\theta\\) 画成时间路径是类别错误。也不要把符号定理当成定量：隐函数给局部线性近似，大扰动可以翻号（吉芬、多重均衡）。</p><p><span class="marginnote">Samuelson 的对应原理想用动态稳定限制比较静态符号。有用但不万能：稳定仍可能留下未定号的交叉项。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>三条常用路。(1) 直接隐函数：写出 \\(D_x F\\)，判断对角或二次型符号。(2) 包络加恒等式：先对 \\(V\\) 求导两次交叉，用 Young 对称得到 \\(Dx\\) 的对称性（斯勒茨基对称）。(3) 单调方法：目标对 \\((x,\\theta)\\) 超模或单交叉，则 \\(x^*(\\theta)\\) 单调，无需可微——机制设计、寡头里更常见。主干微观先会 (1)(2)；非光滑或离散选择走 (3)。</p><p>无差异的参数（计价物缩放）必须先消掉，否则 \\(D_x F\\) 奇异。后课<a href="/econ/walras-law-numeraire">瓦尔拉斯定律与计价物</a>处理均衡侧；优化侧则是预算的一次齐次。比较静态要在归一化之后做。</p>',12)),(e(),s(E,null,{default:o(()=>[p(r,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20F%5B%22%E6%96%B9%E7%A8%8B%20F(x%2Ctheta)%3D0%22%5D%20--%3E%20IFT%5B%22%E9%9A%90%E5%87%BD%E6%95%B0%E7%BB%99%E5%87%BA%20Dx%22%5D%0A%20%20IFT%20--%3E%20SIGN%5B%22%E4%BA%8C%E9%98%B6%E7%BB%93%E6%9E%84%E5%AE%9A%E5%8F%B7%22%5D%0A%20%20ENV%5B%22%E5%8C%85%E7%BB%9C%E4%BA%A4%E5%8F%89%E5%AF%BC%E6%95%B0%22%5D%20--%3E%20SYM%5B%22%E5%AF%B9%E7%A7%B0%EF%BC%9A%E6%96%AF%E5%8B%92%E8%8C%A8%E5%9F%BA%22%5D%0A%20%20SIGN%20--%3E%20STAT%5B%22%E7%A8%B3%E6%80%81%E5%AF%B9%E7%A8%B3%E6%80%81%22%5D%0A%20%20SYM%20--%3E%20STAT%0A%20%20STAT%20--%3E%20DYN%5B%22%E5%8A%A8%E6%80%81%E8%B7%AF%E5%BE%84%E4%BA%A4%E7%BB%99%E5%90%8E%E8%AF%BE%E4%B8%8D%E5%8A%A8%E7%82%B9%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[c(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>二阶充分条件给 \\(D_x F\\) 一块负定（或加边负定）。右端 \\(D_\\theta F\\) 说参数往哪推一阶条件。负定矩阵的逆仍保持「自身项」的符号倾向：把自身价格放进 \\(D_\\theta F\\)，自身需求倾向下降——这是替代效应的二阶来源。收入效应来自预算那一项，可正可负，于是总效应可正可负。比较静态的诚实表述是：能定号的写定号，定不了的停，不要用故事补符号。</p><p>集值最优没有 \\(Dx\\)。凸偏好不严格时，价格微动可以沿整段需求滑动。那时比较静态改成：最优对应的上半连续与单调（强集值意义下），而不是导数。这是后课 UHC 的伏笔。</p><p><span class="marginnote">定量比较静态需要校准或估计 Jacobian。本栏数学课只准备符号与局部线性；实证识别是计量主干，不在此展开。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不在本课写完整斯勒茨基证明，不进入限价簿的价格冲击，不把 CAPM 的 beta 实证当例子。吉芬商品是合法的符号失败，留给<a href="/econ/giffen-inferior">吉芬与劣等</a>。下一课离开局部导数，问全局：迭代映射何时收敛到唯一不动点。</p><p>后课默认：内部非退化最优的局部比较静态 = 隐函数线性方程；自身替代倾向为负；交叉项与收入项另行假设才能定号。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>比较静态读 \\(Dx\\) 的符号，不要求闭式解。</li><li>二阶结构定自身项；交叉项与收入项常常未定。</li><li>包络交叉给出对称；超模给出单调而不靠可微。</li><li>比较的是稳态对稳态，不是调整路径。</li><li>下一课：<a href="/econ/contraction-mapping">压缩映射</a>。</li><li>出处：MWG 第 2–3 章与数学附录；Silberberg, <em>The Structure of Economics</em>。</li></ul>',9))])}const D=i(h,[["render",d]]);export{x as __pageData,D as default};
